import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Providers API","description":"","frontmatter":{},"headers":[],"relativePath":"api/providers.md","filePath":"api/providers.md"}'),o={name:"api/providers.md"};function d(r,e,n,p,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="providers-api" tabindex="-1">Providers API <a class="header-anchor" href="#providers-api" aria-label="Permalink to &quot;Providers API&quot;">​</a></h1><p>Provider endpoints expose installed agent CLI metadata, capabilities, diagnostics, and safe provider-specific command surfaces.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="list-providers" tabindex="-1">List Providers <a class="header-anchor" href="#list-providers" aria-label="Permalink to &quot;List Providers&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers</span></span></code></pre></div><p>Returns registered providers such as <code>claude-code</code> and <code>codex-cli</code>, including install status, version, capabilities, and config paths.</p><p>Capability flags are stable booleans. Unsupported provider surfaces are returned as <code>false</code>; detailed provider-specific state belongs in metadata fields such as backup policy, diagnostics, inventory, or command status.</p><h3 id="provider-status" tabindex="-1">Provider Status <a class="header-anchor" href="#provider-status" aria-label="Permalink to &quot;Provider Status&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/{provider_id}/status</span></span></code></pre></div><p>Returns status for one provider.</p><h3 id="codex-doctor" tabindex="-1">Codex Doctor <a class="header-anchor" href="#codex-doctor" aria-label="Permalink to &quot;Codex Doctor&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/doctor</span></span></code></pre></div><p>Runs Codex diagnostics and returns redacted output.</p><h3 id="codex-inventory" tabindex="-1">Codex Inventory <a class="header-anchor" href="#codex-inventory" aria-label="Permalink to &quot;Codex Inventory&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/features</span></span></code></pre></div><p>Returns Codex MCP, plugin, and feature inventory. Secret-like values are redacted. MCP JSON output is parsed and redacted before any raw output is returned. Plugin text output is treated as read-only text with best-effort row parsing.</p><p>Feature inventory is parsed from <code>codex features list</code> and returns the feature name, stage, and effective enabled state. Removed and deprecated flags may still be present in raw CLI output; the frontend hides those from the main toggle list unless they already exist as explicit config overrides.</p><h3 id="codex-mcp-mutation" tabindex="-1">Codex MCP Mutation <a class="header-anchor" href="#codex-mcp-mutation" aria-label="Permalink to &quot;Codex MCP Mutation&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/mcp/{name}</span></span></code></pre></div><p>Adds or removes Codex MCP servers through the Codex CLI with strict validation.</p><h3 id="codex-plugin-mutation" tabindex="-1">Codex Plugin Mutation <a class="header-anchor" href="#codex-plugin-mutation" aria-label="Permalink to &quot;Codex Plugin Mutation&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/plugins/{name}</span></span></code></pre></div><p>Installs or removes Codex plugins through the Codex CLI when the installed CLI exposes safe commands. Codex plugin enable/disable remains unsupported until Codex exposes a stable safe contract.</p><h3 id="codex-config-profile-diagnostics" tabindex="-1">Codex Config/Profile Diagnostics <a class="header-anchor" href="#codex-config-profile-diagnostics" aria-label="Permalink to &quot;Codex Config/Profile Diagnostics&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/codex-config</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/codex-config/profile-diagnostics</span></span></code></pre></div><p>Returns redacted Codex config summaries, profile-file diagnostics, and active/default profile resolution. Auth, history, cache, and raw secret values are omitted or redacted.</p><h3 id="codex-usage-context-diagnostics" tabindex="-1">Codex Usage/Context Diagnostics <a class="header-anchor" href="#codex-usage-context-diagnostics" aria-label="Permalink to &quot;Codex Usage/Context Diagnostics&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/providers/codex-cli/usage-context-diagnostics</span></span></code></pre></div><p>Returns diagnostics-only metadata for Codex history and model cache shape. This endpoint does not return prompt text, session ids, raw history rows, model ids, raw model cache payloads, auth data, or SQLite contents. Usage and context parity are explicitly unsupported for Codex.</p><h2 id="normalized-provider-errors" tabindex="-1">Normalized Provider Errors <a class="header-anchor" href="#normalized-provider-errors" aria-label="Permalink to &quot;Normalized Provider Errors&quot;">​</a></h2><p>Provider endpoints should surface user-actionable error states:</p><table tabindex="0"><thead><tr><th>Error code/state</th><th>Meaning</th></tr></thead><tbody><tr><td><code>unknown_provider</code></td><td>The requested provider id is not registered.</td></tr><tr><td><code>unsupported_operation</code></td><td>The provider does not support the requested capability.</td></tr><tr><td><code>unsupported_provider_operation</code></td><td>The endpoint exists, but only for another provider.</td></tr><tr><td><code>command_not_allowed</code></td><td>The requested CLI command is outside the provider whitelist.</td></tr><tr><td><code>provider_binary_missing</code></td><td>The provider CLI is not installed or not on <code>PATH</code>.</td></tr><tr><td>CLI failure</td><td>The CLI returned a non-zero exit code; stdout/stderr are redacted.</td></tr><tr><td>Parse failure</td><td>CLI output could not be parsed; raw sensitive payloads are omitted or redacted.</td></tr><tr><td>Validation failure</td><td>User input failed strict validation before any CLI command ran.</td></tr></tbody></table><p>The frontend should use provider status and these error states to disable unsupported controls instead of routing Codex users to Claude-only pages.</p>`,33)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
